WAREHOUSE = ("a big grey warehouse labelled 'WAREHOUSE' with huge doors, piled high inside with stacks of shiny trading cards; "
             "a small stickman guard in a cap at a tiny window letting out just a few cards")
VAULT = "a big old bank-style vault room filled with shelves of small paper parcels and boxes of sparkling diamonds"

R = []
_cnt = [0]
TAG = {}
def row(n, anchor, typ, beeld, era="none", ref=None, tag=None):
    """ref: list of tags (resolved to row numbers at the end), tag: name of this row for later references."""
    if isinstance(n, int) or str(n).isdigit():
        _cnt[0] += 1; n = _cnt[0]   # numbers are assigned in order
    if tag:
        TAG[tag] = str(n)
    R.append({"n": str(n), "anchor": anchor, "type": typ, "beeld": beeld, "era": era, "ref": ref or []})

